    );
    return;
  }
  app.append(h("ol", {class: "q-list"},
    survey.questions.map((q, i) => h("li", null,
      h("div", {class: "q-line"},
        `${i + 1}. ${q.title} `,
        h("span", {class: "tag"}, q.type === "single_choice" ? "单选题" : "文本题"),
        " ",
        h("span", {class: "tag" + (q.required ? " required" : "")}, q.required ? "必填" : "选填")
      ),
