    # ---------- 离开后重新进入同一份问卷的编辑页 ----------

    def _leave_and_reenter_same_edit(self, survey_id):
        # 经“取消”到详情，再点“编辑草稿”重新进入：编号与地址相同，但是全新一代表单。
