    # ---------- 四、删除重复选项后保存 / 删到只剩一个 ----------

    def test_delete_duplicate_option_then_save_with_remaining_two(self):
        """删除重复项后仍有两个非空不重复选项：允许保存，剩余选项按顺序落库。"""
