        self.assertFalse(detail["anyVisibleBanner"])
        self.assertEqual(len(detail["questions"]), 2)
        q1_line, q2_line = detail["questions"][0]["line"], detail["questions"][1]["line"]
        self.assertIn("您的满意度？", q1_line)
