        # 选项按原顺序，去掉首尾空白，内部换行保留为同一个选项。
        self.assertEqual(detail["questions"][0]["options"],
                         ["满意", "一般\n换行", "不满意"])
        self.assertEqual(detail["questions"][1]["options"], [])

        # 接口落库结果与详情一致。
        self.assert_saved_survey(new_id, {
            "title": "年度满意度问卷",
            "description": desc_raw,
            "questions": [
